#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        LeakRate::new(v, LeakRateUnit::PascalCubicMeterPerSecond),
        LeakRate::from_pascal_cubic_meters_per_second(v)
    );
    assert_eq!(
        LeakRate::from_base(v).convert_to(LeakRateUnit::PascalCubicMeterPerSecond),
        LeakRate::from_base(v).as_pascal_cubic_meters_per_second()
    );
    assert_eq!(
        LeakRate::new(v, LeakRateUnit::MillibarLiterPerSecond),
        LeakRate::from_millibar_liters_per_second(v)
    );
    assert_eq!(
        LeakRate::from_base(v).convert_to(LeakRateUnit::MillibarLiterPerSecond),
        LeakRate::from_base(v).as_millibar_liters_per_second()
    );
    assert_eq!(
        LeakRate::new(v, LeakRateUnit::TorrLiterPerSecond),
        LeakRate::from_torr_liters_per_second(v)
    );
    assert_eq!(
        LeakRate::from_base(v).convert_to(LeakRateUnit::TorrLiterPerSecond),
        LeakRate::from_base(v).as_torr_liters_per_second()
    );
    assert_eq!(
        LeakRate::new(v, LeakRateUnit::AtmCubicCentimeterPerSecond),
        LeakRate::from_atm_cubic_centimeters_per_second(v)
    );
    assert_eq!(
        LeakRate::from_base(v).convert_to(LeakRateUnit::AtmCubicCentimeterPerSecond),
        LeakRate::from_base(v).as_atm_cubic_centimeters_per_second()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = LeakRate::from_base(v);
        let auto = q.auto_unit();
        assert_close(LeakRate::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in LeakRateUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        LeakRate::from_base(0.0).auto_unit().unit,
        LeakRateUnit::PascalCubicMeterPerSecond
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Pa·m³/s".parse::<LeakRateUnit>(),
        Ok(LeakRateUnit::PascalCubicMeterPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Pa·m³/s").parse::<LeakRate>(),
        Ok(LeakRate::new(2.5, LeakRateUnit::PascalCubicMeterPerSecond))
    );
    assert_eq!(
        "mbar·l/s".parse::<LeakRateUnit>(),
        Ok(LeakRateUnit::MillibarLiterPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mbar·l/s").parse::<LeakRate>(),
        Ok(LeakRate::new(2.5, LeakRateUnit::MillibarLiterPerSecond))
    );
    assert_eq!(
        "Torr·l/s".parse::<LeakRateUnit>(),
        Ok(LeakRateUnit::TorrLiterPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Torr·l/s").parse::<LeakRate>(),
        Ok(LeakRate::new(2.5, LeakRateUnit::TorrLiterPerSecond))
    );
    assert_eq!(
        "atm·cm³/s".parse::<LeakRateUnit>(),
        Ok(LeakRateUnit::AtmCubicCentimeterPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "atm·cm³/s").parse::<LeakRate>(),
        Ok(LeakRate::new(
            2.5,
            LeakRateUnit::AtmCubicCentimeterPerSecond
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<LeakRate>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = LeakRate::from_base(6.0);
    let b = LeakRate::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = LeakRate::<i64>::from_base(7);
    let b = LeakRate::<i64>::from_base(2);
    assert_eq!(a + b, LeakRate::from_base(9));
    assert_eq!(a % b, LeakRate::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<LeakRate<i64>>(), LeakRate::from_base(9));
}
